insert into public.course_categories (name) values ($wdthseed$Science$wdthseed$) on conflict (name) do nothing;
insert into public.courses (title, slug, description, thumbnail_url, price, duration, difficulty_level, is_published, published, archived, learning_outcomes, prerequisites, learning_objectives, level, category, metadata, category_id) values ($wdthseed$Biology — Complete Secondary & Foundation Course$wdthseed$, $wdthseed$biology$wdthseed$, $wdthseed$This is a complete, classroom-ready biology course for secondary, senior secondary and foundation-level students. It covers the full scheme of work: foundations of biology, cell biology, biological molecules, cell division, genetics, evolution, ecology, human biology, plant biology and practical biology, followed by structured revision and a final examination. Every lesson contains original WOLI DAN TECH HUB teaching material — theory, worked examples, key concepts and summaries — plus verified videos and open textbooks. Each module includes a hands-on practical activity, a written assignment, a quiz and a module examination. To complete the course and earn a certificate, students must finish at least 80% of lessons, keep a quiz average of 60% or above, pass every assignment and pass the final examination.$wdthseed$, NULL, 5000, $wdthseed$12 weeks$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, TRUE, TRUE, FALSE, $wdthseed$["Define and apply the seven characteristics of living organisms","Label plant and animal cells and state the function of each organelle","Test foods for starch, sugar, protein and fats and explain each test","Describe mitosis and meiosis and compare their outcomes","Use Punnett squares to predict genotypes and phenotypes","Explain how natural selection produces adaptation over generations","Construct food chains and pyramids and explain energy loss","Trace digestion, circulation and gaseous exchange in humans","Write the photosynthesis equation and explain limiting factors","Use a light microscope safely and calculate total magnification","Plan, record and evaluate a simple biological investigation","Score at least 60% in the final biology examination"]$wdthseed$::jsonb, $wdthseed$["Basic English reading and writing","Primary-school mathematics (fractions, percentages, simple graphs)","No previous biology required — Module 1 starts from zero"]$wdthseed$::jsonb, $wdthseed$["Describe the characteristics of living things and levels of biological organisation","Explain cell structure, transport processes and cell division","Classify biological molecules and explain enzyme action","Solve Mendelian genetics problems including monohybrid crosses","Explain natural selection and the evidence for evolution","Analyse ecosystems, food chains, nutrient cycles and human impact","Describe the major human body systems and how they stay balanced","Explain photosynthesis, transport and reproduction in flowering plants","Carry out safe biology practicals including microscopy and food tests","Interpret biological data, graphs and examination questions accurately"]$wdthseed$::jsonb, $wdthseed$Secondary / Senior Secondary / Foundation$wdthseed$, $wdthseed$Science$wdthseed$, $wdthseed${"short_description":"A complete biology course from the characteristics of life to genetics, ecology, human and plant biology — with practicals, quizzes and a final examination.","subcategory":"Life Sciences","study_hours":120,"target_audience":["Junior and senior secondary school students","Students preparing for WAEC, NECO and JAMB biology","Foundation and pre-degree science students","Adult learners starting a science pathway"],"skills_gained":["Scientific observation and classification","Microscopy and biological drawing","Safe laboratory practice","Data handling: tables, graphs and magnification calculations","Genetic problem solving with Punnett squares","Experimental design and conclusion writing","Examination technique for science papers"],"requirements":["A notebook or device for study notes","Pen, pencil and ruler for biological drawings","Access to the internet for videos and quizzes (low-bandwidth friendly)","For practicals: household-safe materials listed in each activity (no dangerous chemicals)"],"instructor_name":"WOLI DAN TECH HUB Science Faculty","icon":"microscope","syllabus_version":1}$wdthseed$::jsonb, (select id from public.course_categories where name = $wdthseed$Science$wdthseed$)) on conflict (slug) do update set title = excluded.title, description = excluded.description, thumbnail_url = excluded.thumbnail_url, price = excluded.price, duration = excluded.duration, difficulty_level = excluded.difficulty_level, is_published = excluded.is_published, published = excluded.published, archived = excluded.archived, learning_outcomes = excluded.learning_outcomes, prerequisites = excluded.prerequisites, learning_objectives = excluded.learning_objectives, level = excluded.level, category = excluded.category, metadata = excluded.metadata, category_id = excluded.category_id;
insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod01$wdthseed$, $wdthseed$Foundations of Biology$wdthseed$, $wdthseed$What biology studies, the characteristics that separate living things from non-living things, levels of organisation, and how scientists classify and identify organisms.$wdthseed$, 1, $wdthseed${"objectives":["Define biology and its main branches","List and apply the seven characteristics of living things","Order the levels of biological organisation","Classify organisms into the five kingdoms and use a simple identification key"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod01:top01$wdthseed$, $wdthseed$What Is Biology?$wdthseed$, $wdthseed$The science of life: what biologists study, the characteristics of living things, and how life is organised from cells to ecosystems.$wdthseed$, NULL, 1, TRUE, TRUE, $wdthseed${"objectives":["Define biology","Apply the characteristics of life to real specimens"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod01:top01:les01$wdthseed$, $wdthseed$The Science of Life$wdthseed$, $wdthseed$What biology is, its major branches, and the seven characteristics shared by all living things.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=cQPVXrV0GNA$wdthseed$, $wdthseed$Biology is the scientific study of life — from a single bacterial cell to a whole rainforest. Before we study cells, genes and ecosystems, we must answer one question precisely: what does it mean to be alive?
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Biology and its branches$wdthseed$, $wdthseed$Biology comes from the Greek bios (life) and logos (study). It asks how living things are built, how they work, where they came from, and how they interact. Because life is so broad, biology splits into branches. Zoology studies animals; botany studies plants; microbiology studies organisms too small to see, such as bacteria; genetics studies inheritance; ecology studies how organisms relate to each other and their environment; anatomy studies body structures; and physiology studies how those structures function. Modern biology connects all of these: a doctor treating malaria uses microbiology (the Plasmodium parasite), ecology (mosquito breeding sites), genetics (drug resistance) and physiology (how the human body responds). Like all sciences, biology works through observation, hypotheses, controlled experiments and peer-reviewed evidence — not opinion. Throughout this course you will practise thinking like a biologist: observe carefully, measure where possible, and change your mind when the evidence demands it.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The seven characteristics of living things$wdthseed$, $wdthseed$Biologists recognise seven characteristics shared by all known living things. A useful memory aid is MRS GREN: Movement (all living things can move — animals walk, plants turn leaves toward light, cells stream their cytoplasm); Respiration (releasing energy from food, aerobically or anaerobically); Sensitivity (detecting and responding to stimuli, such as a seedling bending toward light); Growth (permanent increase in size through cell division); Reproduction (producing offspring, sexually or asexually); Excretion (removing toxic waste products of metabolism, such as carbon dioxide and urea); and Nutrition (taking in and using food for energy and building materials). No single characteristic proves life — a car moves and uses fuel but does not grow, reproduce or excrete. An object is considered living only when it shows ALL seven. This strict rule is why viruses are usually called non-living: outside a host cell they show none of the seven, even though they carry genetic material.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: is a dry bean seed alive?$wdthseed$, $wdthseed$Question: A dry bean seed shows no movement, no growth and no gas exchange. Is it alive? Answer step by step. Step 1 — List what we observe: the seed is dormant; metabolism is nearly stopped. Step 2 — Ask whether ALL seven characteristics are potentially present: given water, warmth and air, the seed germinates — it respires, grows, responds to gravity and light, and eventually reproduces. Its cells are organised and contain the full genetic programme. Step 3 — Conclude: the seed IS alive but dormant. Dormancy is a survival state with metabolism slowed almost to zero, not death. Contrast this with a boiled bean seed: its proteins are denatured and its cells destroyed, so it can never germinate — it is dead. Examination tip: always argue from evidence — state the observation, link it to a characteristic of life, then conclude.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Characteristics of Life$wdthseed$, $wdthseed$Watch 'Characteristics of Life' by the Amoeba Sisters (streamed from their official channel). As you watch, write one example from YOUR home or compound for each of the seven characteristics — for instance, the family goat for movement, or bean seedlings for growth.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=cQPVXrV0GNA$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Biology = the scientific study of life, built on evidence from observation and experiment.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Biology studies life through its branches — zoology, botany, microbiology, genetics, ecology, anatomy and physiology — united by the scientific method. Living things show all seven MRS GREN characteristics; non-living things fail at least one. Judging borderline cases (seeds, viruses, fire) by evidence rather than feeling is your first skill as a biologist.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_videos (seed_key, title, video_url, duration, status, provider, language, transcript, provider_metadata, lesson_id, course_id, module_id, topic_id) values ($wdthseed$biology:mod01:top01:les01:vid1$wdthseed$, $wdthseed$Characteristics of Life$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=cQPVXrV0GNA$wdthseed$, NULL, $wdthseed$COMPLETED$wdthseed$::public.video_job_status, $wdthseed$youtube$wdthseed$, $wdthseed$en$wdthseed$, $wdthseed$The seven characteristics of life explained with animations and everyday examples.$wdthseed$, $wdthseed${"source":"Amoeba Sisters","license":"Standard YouTube License (official stream — no copy made)","attribution":"© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters"}$wdthseed$::jsonb, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod01:top01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, video_url = excluded.video_url, duration = excluded.duration, status = excluded.status, provider = excluded.provider, language = excluded.language, transcript = excluded.transcript, provider_metadata = excluded.provider_metadata, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod01:top01:les01:vid1:res$wdthseed$, $wdthseed$Characteristics of Life$wdthseed$, $wdthseed$The seven characteristics of life explained with animations and everyday examples.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=cQPVXrV0GNA$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod01:top01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod01:top01:les02$wdthseed$, $wdthseed$Levels of Organisation$wdthseed$, $wdthseed$How life builds up from atoms to ecosystems, and why each level has new properties.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A single atom of carbon is not alive — yet arranged with other atoms into cells, it becomes part of a living mango tree. Organisation is what turns chemistry into biology.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$From atoms to ecosystems$wdthseed$, $wdthseed$Living things are organised in a hierarchy, and each level is built from the one below: atoms join into molecules (such as water, proteins and DNA); molecules assemble into organelles (tiny cell structures like the nucleus and mitochondria); organelles work inside cells, the basic units of life; similar cells group into tissues (muscle tissue, leaf epidermis); tissues form organs (heart, leaf, root); organs cooperate in organ systems (circulatory system, shoot system); systems make an organism (a goat, a maize plant); organisms of one species form a population; populations of different species sharing a habitat form a community; and the community plus its non-living environment (soil, water, air, sunlight) forms an ecosystem. Learn this chain in order: atom, molecule, organelle, cell, tissue, organ, system, organism, population, community, ecosystem.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Emergent properties$wdthseed$, $wdthseed$Each level of organisation shows emergent properties — new behaviours that the parts alone do not have. A single nerve cell cannot feel pain, but billions wired together produce sensation. One water molecule is not wet; trillions together flow and dissolve. Emergence is why biologists study every level: you cannot fully explain a fever by staring at one white blood cell, nor predict a fishpond's harvest from one tilapia. Reduction (studying parts) and systems thinking (studying wholes) must work together. This idea returns throughout the course — for example, consciousness emerging from brain cells, or an epidemic emerging from individual infections.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: placing specimens at the right level$wdthseed$, $wdthseed$Question: Place each item at its level — (a) blood, (b) a cassava leaf, (c) all the tilapia in a pond, (d) the pond with its water, mud and sunlight. Step 1 — Recall definitions: tissue = similar cells working together; organ = tissues working together; population = one species in an area; ecosystem = community + environment. Step 2 — Match: (a) blood is a tissue (red cells, white cells, platelets in plasma working together); (b) a leaf is an organ (epidermis, mesophyll, veins); (c) all tilapia of one pond are a population; (d) the pond with everything living and non-living is an ecosystem. Common examination trap: blood is a TISSUE, not an organ or system — memorise this.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Atom → molecule → organelle → cell → tissue → organ → system → organism → population → community → ecosystem.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Life is a hierarchy from atoms to ecosystems. The cell is the lowest level that is fully alive, and every level above it gains emergent properties. Placing structures at the correct level is a favourite examination skill — practise with objects around you.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod01:top02$wdthseed$, $wdthseed$Classification of Living Things$wdthseed$, $wdthseed$Why biologists classify organisms, the five kingdoms, and how identification keys work.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Justify classification","Assign organisms to kingdoms","Use a dichotomous key"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod01:top02:les01$wdthseed$, $wdthseed$The Five Kingdoms$wdthseed$, $wdthseed$How millions of species are sorted into five great kingdoms, and where viruses fit.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Scientists have named about two million species, and millions more await discovery. Without a filing system, biology would be chaos — classification is that filing system.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Why classify?$wdthseed$, $wdthseed$Classification groups organisms by shared features so that knowledge transfers: learn how one mammal's heart works and you understand all mammals' hearts approximately. It reveals evolutionary relationships — lions and house cats share the order Carnivora because they share a recent ancestor. It also makes communication precise: the two-part scientific name (binomial nomenclature) gives every species exactly one global identity. Humans are Homo sapiens everywhere on Earth — no confusion from the thousands of local names. Names are written in italics (or underlined by hand), with the genus capitalised and the species lowercase: Mangifera indica (mango), Plasmodium falciparum (the malaria parasite).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The five kingdoms$wdthseed$, $wdthseed$The five-kingdom system sorts life by cell type, cell number and nutrition. (1) Monera (bacteria): prokaryotic, single-celled; some make food by photosynthesis or chemosynthesis, others absorb it — examples: Escherichia coli, Rhizobium in bean root nodules. (2) Protista: eukaryotic, mostly single-celled; plant-like (Euglena, diatoms), animal-like (Amoeba, Plasmodium) or fungus-like (slime moulds). (3) Fungi: eukaryotic, mostly multicellular; feed saprophytically by digesting dead matter externally — examples: mushroom, Rhizopus (bread mould), yeast. (4) Plantae: eukaryotic, multicellular, autotrophic (photosynthesis), with cell walls of cellulose — examples: maize, mango, mosses. (5) Animalia: eukaryotic, multicellular, heterotrophic (must eat), no cell walls, usually mobile — examples: goat, tilapia, earthworm, humans. Viruses belong to NO kingdom: they are particles of nucleic acid in protein, reproduce only inside host cells, and show no metabolism — the classic borderline case from Lesson 1.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: kingdom of bread mould$wdthseed$, $wdthseed$Question: Bread left in a damp place grows grey-black fuzz with tiny round heads. Which kingdom, and why? Step 1 — Observe: fuzzy threads (hyphae) spreading over the bread, round spore heads (sporangia). Step 2 — Check kingdom features: the threads are eukaryotic cells without chlorophyll; it digests the bread externally and absorbs nutrients (saprophytic); it reproduces with spores. Step 3 — Conclude: Kingdom Fungi — specifically a mould like Rhizopus. It is NOT a plant (no photosynthesis, no true roots/stems/leaves) and NOT a bacterium (eukaryotic, visible threads). Examination tip: justify with at least two features, and always say what rules the alternatives OUT.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Classification transfers knowledge, reveals ancestry and gives each species one scientific name.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$With millions of species, biology needs classification to stay organised and predictive. The five kingdoms divide life by cell structure and feeding, scientific names keep communication exact, and viruses remind us that nature does not always fit our boxes.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod01:top02:les02$wdthseed$, $wdthseed$Identification Keys$wdthseed$, $wdthseed$How biologists identify unknown specimens step by step using dichotomous keys.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$You find an insect you have never seen. Is it a pest, a pollinator, or harmless? A dichotomous key answers such questions with a chain of either-or choices.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$How dichotomous keys work$wdthseed$, $wdthseed$A dichotomous key is a series of paired statements (a couplet) where exactly one fits your specimen; each answer sends you to the next couplet until only one identity remains. Good couplets use observable, unambiguous features — number of legs, presence of wings, leaf shape — never vague words like 'big' or 'pretty'. Keys exist for plants, insects, fish, animal tracks and even bacteria (using staining and biochemical tests). Following a key trains the same skill doctors use in diagnosis and mechanics use in fault-finding: eliminate possibilities systematically instead of guessing.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: keying out four insects$wdthseed$, $wdthseed$Specimens: housefly, mosquito, butterfly, beetle. Key: 1a. Wings covered in tiny coloured scales → butterfly. 1b. Wings without scales → go to 2. 2a. Front wings hardened into covers (elytra) → beetle. 2b. Front wings membranous → go to 3. 3a. One pair of wings + halteres (balancing knobs) → housefly. 3b. One pair of wings, long legs, piercing mouthparts → mosquito. Now identify: your specimen has one pair of clear wings, long dangling legs and a needle-like mouth. Path: 1b → 2b → 3b = mosquito. Notice the discipline: at each step you commit to ONE branch based on OBSERVED features. If a specimen fits neither branch, the key does not cover it — report that honestly rather than forcing a wrong answer.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Dichotomous = branching in twos; each couplet offers exactly two contrasting choices.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod01:top02:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Dichotomous keys turn identification into reliable step-by-step elimination. Master them and you gain a method used across biology, medicine and engineering — plus easy marks in practical examinations.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod01:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 1 reading: Chapter 1 (The Study of Life) for characteristics of life and levels of organisation; Chapters 21–23 for viruses, prokaryotes and protists. Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod01:prac$wdthseed$, $wdthseed$Living or Non-Living? A Home Survey$wdthseed$, $wdthseed$Apply the seven characteristics of life to ten real objects and classify each as living, dormant, dead or never-alive.$wdthseed$, $wdthseed$Your compound is a field site. You will survey it like an ecologist and record evidence for each characteristic.$wdthseed$, $wdthseed$1. Choose 10 items: include at least one plant, one animal (observe without harming), one seed, one man-made object and one thing you are unsure about. 2. Draw a table with columns: Item | M | R | S | G | R | E | N | Verdict. 3. For each item, observe or recall evidence for every MRS GREN characteristic and tick or cross each column — you may research briefly (e.g. do banana plants reproduce?). 4. Give a verdict: LIVING (all seven, actually or potentially), DORMANT (alive, paused), DEAD (was alive, now none) or NEVER-ALIVE. 5. Write two sentences justifying your two hardest verdicts. SAFETY: do not touch unknown animals, sharp objects or stagnant water; wash hands afterwards.$wdthseed$, $wdthseed$Notebook, pen, phone camera (optional, for evidence photos).$wdthseed$, $wdthseed$A completed 10-row table plus two written justifications (4–6 sentences total).$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 60, $wdthseed$TEXT$wdthseed$, $wdthseed$["All 10 rows completed with honest ticks/crosses","Correct verdicts with evidence (seeds dormant, fire never-alive)","Justifications reference specific characteristics, not feelings"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod01:asg$wdthseed$, $wdthseed$Build a Key for Five Local Organisms$wdthseed$, $wdthseed$Construct an original dichotomous key that identifies five organisms found in your area.$wdthseed$, $wdthseed$1. Select FIVE different organisms you can observe (e.g. mango tree, housefly, earthworm, mushroom, tilapia from the market). 2. List at least six observable features for each. 3. Build a numbered dichotomous key (1a/1b, 2a/2b...) that separates all five — every branch must end in exactly one organism. 4. Test your key: give it to a friend or sibling with the five names hidden and record whether they identify all five correctly. 5. Submit the key plus a short paragraph on what you changed after testing. Minimum 300 words plus the key.$wdthseed$, $wdthseed$Observations must be your own; keys copied from the internet score zero for originality.$wdthseed$, $wdthseed$A working 5-organism key and a test report paragraph.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Five distinct local organisms with real observable features","Key is strictly dichotomous and identifies all five uniquely","Test report shows honest testing and at least one improvement"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
insert into public.quizzes (seed_key, title, description, passing_score, time_limit, status, scope, order_number, metadata, course_id, module_id, lesson_id) values ($wdthseed$biology:mod01:quiz$wdthseed$, $wdthseed$Module 1 Quiz — Foundations$wdthseed$, $wdthseed$Quick check on the characteristics of life, levels of organisation and classification.$wdthseed$, 70, 15, $wdthseed$PUBLISHED$wdthseed$::public.content_status, $wdthseed$MODULE$wdthseed$, 1, $wdthseed${"attempt_limit":3,"points_total":5}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod01:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, passing_score = excluded.passing_score, time_limit = excluded.time_limit, status = excluded.status, scope = excluded.scope, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod01:quiz:q01$wdthseed$, $wdthseed$Which set lists ONLY characteristics of living things?$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Movement, respiration, sensitivity, growth, reproduction, excretion, nutrition","Movement, hardness, colour, growth, weight, excretion, nutrition","Respiration, photosynthesis, digestion, circulation, coordination, support, movement","Growth, development, evolution, digestion, absorption, transport, coordination"]$wdthseed$::jsonb, $wdthseed$"Movement, respiration, sensitivity, growth, reproduction, excretion, nutrition"$wdthseed$::jsonb, $wdthseed$MRS GREN is the complete set: Movement, Respiration, Sensitivity, Growth, Reproduction, Excretion, Nutrition. The other lists mix in non-characteristics (hardness, colour) or processes that are not universal (photosynthesis).$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Characteristics of life"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod01:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
