insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod01:quiz:q02$wdthseed$, $wdthseed$Fire moves, grows and releases energy. Why is it NOT alive?$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["It is too hot to touch","It is not made of cells and shows no organisation, reproduction or excretion","It has no colour","It cannot be seen at night"]$wdthseed$::jsonb, $wdthseed$"It is not made of cells and shows no organisation, reproduction or excretion"$wdthseed$::jsonb, $wdthseed$Fire fails most MRS GREN tests: no cells, no true growth by cell division, no reproduction, no sensitivity or excretion. Resembling one or two characteristics is not enough.$wdthseed$, 2, $wdthseed${"points":1,"topic_tag":"Characteristics of life"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod01:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
