insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod01:quiz:q03$wdthseed$, $wdthseed$Arrange these levels from simplest to most complex: population, cell, ecosystem, organ.$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Cell, organ, population, ecosystem","Cell, population, organ, ecosystem","Organ, cell, ecosystem, population","Ecosystem, population, organ, cell"]$wdthseed$::jsonb, $wdthseed$"Cell, organ, population, ecosystem"$wdthseed$::jsonb, $wdthseed$Cells build organs; organisms of one species form populations; communities plus environment form ecosystems. So: cell → organ → population → ecosystem.$wdthseed$, 3, $wdthseed${"points":1,"topic_tag":"Organisation"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod01:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
