insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod02$wdthseed$, $wdthseed$Cell Biology$wdthseed$, $wdthseed$The cell as the basic unit of life: plant and animal cell structure, prokaryotic versus eukaryotic cells, and how substances move across membranes.$wdthseed$, 2, $wdthseed${"objectives":["Label plant and animal cells and state organelle functions","Compare prokaryotic and eukaryotic cells","Explain diffusion, osmosis and active transport with examples","Calculate magnification and real cell sizes"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
