insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod02:top01:les01$wdthseed$, $wdthseed$Plant and Animal Cells$wdthseed$, $wdthseed$The organelles every student must know, and the three structures that separate plant cells from animal cells.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=6mgkoqcm6Sg$wdthseed$, $wdthseed$Every organism you studied in Module 1 is built from cells. This lesson opens the cell and names its working parts — the vocabulary for the rest of biology.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Organelles and their jobs$wdthseed$, $wdthseed$Both plant and animal cells share these parts. The cell membrane (a thin, partially permeable skin of lipid and protein) controls what enters and leaves. The cytoplasm is the jelly-like fluid where most reactions happen. The nucleus stores DNA — the instructions for building and running the cell — and controls cell activities; inside it, the nucleolus makes ribosomes. Mitochondria release energy from glucose during respiration, so active cells (muscle, root hair) contain many. Ribosomes build proteins from amino acids. The endoplasmic reticulum (ER) is a folded membrane network: rough ER (studded with ribosomes) folds new proteins, smooth ER makes lipids. The Golgi body receives, packages and ships proteins in vesicles. Lysosomes contain digestive enzymes that break down waste (common in animal cells). Vacuoles store substances — animal cells have small temporary ones. Plant cells add three extras: a rigid cellulose cell wall for support, chloroplasts containing chlorophyll for photosynthesis, and one large permanent central vacuole that keeps the cell turgid with cell sap.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$How to learn cells for examinations$wdthseed$, $wdthseed$Examiners test cells through labelled diagrams and function questions. Learn each organelle as a pair: STRUCTURE + FUNCTION + ADAPTATION. Example: mitochondrion — folded inner membrane (cristae) gives a large surface area for respiration enzymes; muscle cells pack in thousands. Exam traps to avoid: (1) the cell wall and cell membrane are different structures — do not swap them; (2) chloroplasts trap light energy, mitochondria release energy — opposite jobs; (3) the large permanent vacuole belongs to mature plant cells only. When drawing cells, use a sharp pencil, single (not sketchy) lines, no shading, and straight label lines that touch the structure — biological drawing rules are marked strictly in practical papers.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: identifying cell X$wdthseed$, $wdthseed$Question: Cell X has a cell wall, chloroplasts and a large vacuole. Cell Y has no wall, many mitochondria and small vacuoles. Identify each and justify. Step 1 — Match diagnostic features: wall + chloroplasts + large vacuole occur together ONLY in plant cells, so X is a plant cell (likely a leaf mesophyll cell). Step 2 — Y lacks all three plant extras and is rich in mitochondria, fitting an active animal cell (such as muscle). Step 3 — State what each does with its specialisation: X photosynthesises and stays rigid through turgor; Y contracts using ATP from its mitochondria. Full marks need the identification PLUS at least two justified features each.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Cell Organelles and Structures Review$wdthseed$, $wdthseed$Watch 'Cell Organelles and Structures Review' by the Amoeba Sisters (official channel stream). Pause after each organelle and say its function aloud before the video reveals it — active recall doubles retention.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=6mgkoqcm6Sg$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Membrane controls entry; nucleus holds DNA; mitochondria release energy; ribosomes build proteins; ER folds/makes molecules; Golgi packages; lysosomes digest waste.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Cells are organised teams of organelles. Plant and animal cells share the core machinery for life; plants add a wall, chloroplasts and a large vacuole for support, photosynthesis and turgor. Knowing what each part does — and proving it in labelled diagrams — unlocks every later module.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
