insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod02:top01:les01:vid1:res$wdthseed$, $wdthseed$Cell Organelles and Structures Review$wdthseed$, $wdthseed$Rapid-fire organelle review in a Name-That-Structure format — ideal for self-testing.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=6mgkoqcm6Sg$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod02$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod02:top01$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod02:top01:les02$wdthseed$, $wdthseed$Prokaryotic versus Eukaryotic Cells$wdthseed$, $wdthseed$Why bacteria are built differently, and what the size difference means for how cells work.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A bacterium and a human cheek cell are both alive, but one is a studio apartment and the other a mansion. Size and internal organisation change everything about how a cell lives.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Two cell designs$wdthseed$, $wdthseed$Prokaryotic cells (bacteria and archaea) are small — typically 1 to 5 micrometres — with DNA in a single circular chromosome free in the cytoplasm (the nucleoid region, not a true nucleus), no membrane-bound organelles, small 70S ribosomes, and often a cell wall, slime capsule, plasmids (small DNA rings carrying bonus genes such as antibiotic resistance) and flagella for movement. Eukaryotic cells (plants, animals, fungi, protists) are larger — typically 10 to 100 micrometres — with DNA in linear chromosomes inside a membrane-bound nucleus, membrane-bound organelles (mitochondria, ER, Golgi), larger 80S ribosomes, and complex internal transport. The word roots help: pro = before (no nucleus), eu = true (true nucleus). Mitochondria and chloroplasts probably began as engulfed bacteria — the endosymbiotic theory — which is why they still carry their own small circular DNA.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Why cells are microscopic$wdthseed$, $wdthseed$As a cell grows, its volume (which demands food and produces waste) grows as the CUBE of its radius, while its surface area (which supplies and removes) grows only as the SQUARE. Double a cell's width and it needs 8x the supplies through only 4x the membrane — it starves. This surface-area-to-volume crisis forces cells to stay small, divide, or fold their membranes (root hairs, villi, cristae all do this). Bacteria exploit smallness brilliantly: huge surface area per volume means blistering-fast exchange, letting E. coli divide every 20 minutes in warm food — which is also why food poisoning strikes so fast.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: magnification calculation$wdthseed$, $wdthseed$Question: A cheek cell image is 60 mm wide in your drawing. The magnification is x400. What is the real width in micrometres? Step 1 — Formula: real size = image size ÷ magnification. Step 2 — Substitute: 60 mm ÷ 400 = 0.15 mm. Step 3 — Convert: 1 mm = 1000 micrometres, so 0.15 × 1000 = 150 micrometres. Answer: 150 µm (a realistic cheek-cell width). Examination format: always show the formula, substitution and units — method marks are awarded even if arithmetic slips. Triangle memory aid: cover what you want — I = image, M = magnification, A = actual (I = M × A).$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Prokaryotic: small, no true nucleus, circular DNA, no membrane-bound organelles, 70S ribosomes.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Life uses two cell designs: simple, speedy prokaryotes and compartmentalised eukaryotes. Both obey the same physics — exchange happens at surfaces, so smallness wins. Magnification maths turns microscope images into real measurements.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod02:top02$wdthseed$, $wdthseed$Movement Across Membranes$wdthseed$, $wdthseed$Diffusion, osmosis and active transport — the three ways substances cross cell membranes.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Explain the three transport processes","Predict osmosis direction","Link transport to real organs"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod02:top02:les01$wdthseed$, $wdthseed$Diffusion and Osmosis$wdthseed$, $wdthseed$Passive transport down concentration gradients, and the special case of water.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Your lungs load oxygen and dump carbon dioxide without any pumping by you. Smell from the kitchen reaches your room with no fan. Both are diffusion — physics doing biology's delivery work for free.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Diffusion$wdthseed$, $wdthseed$Diffusion is the net movement of particles from a region of higher concentration to a region of lower concentration, down the concentration gradient, until evenly spread. It needs no energy from the cell — particle motion (kinetic energy) drives it. Four factors speed it up: (1) a steeper concentration gradient, (2) higher temperature (faster particles), (3) larger surface area, and (4) shorter distance (thinner membranes). Examples: oxygen diffusing from alveoli into blood, carbon dioxide diffusing out of leaf cells into air spaces, perfume spreading across a room. Once concentrations equalise, particles still move but there is no NET movement — dynamic equilibrium.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Osmosis$wdthseed$, $wdthseed$Osmosis is the net movement of WATER molecules from a region of higher water concentration (dilute solution) to a region of lower water concentration (concentrated solution) across a partially permeable membrane. Learn this definition word-perfect — examiners reject 'movement of water from high to low concentration' without mentioning the membrane. Consequences: animal cells in pure water swell and burst (lyse) because they have no wall; in concentrated solution they shrivel (crenate). Plant cells in pure water become turgid (firm — the vacuole pushes the membrane against the wall, supporting soft stems); in concentrated solution the membrane pulls away from the wall — plasmolysis — and the plant wilts. Root hairs absorb soil water by osmosis; kidney tubules reabsorb it.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: yam strips in salt solutions$wdthseed$, $wdthseed$Question: Three identical yam strips are placed in distilled water, 5% salt and 20% salt for 30 minutes. Predict the mass change of each. Step 1 — Identify water concentrations: distilled water has the HIGHEST water concentration; 20% salt the LOWEST; yam cells sit between. Step 2 — Apply osmosis: water enters the strip in distilled water (cells become turgid → mass GAIN); water leaves the strip in 20% salt (plasmolysis → mass LOSS); 5% salt is close to cell concentration so little change. Step 3 — State the pattern: mass change follows the water-concentration gradient across the yam cell membranes. This exact experiment is your module practical — predictions first, then measurement.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Diffusion: net particle movement down a concentration gradient; no cell energy needed.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Diffusion delivers gases and dissolved substances for free; osmosis is diffusion of water through membranes. Turgor, wilting, bursting and shrivelling are all osmosis in action — predict them by comparing water concentrations on the two sides.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod02:top02:les02$wdthseed$, $wdthseed$Active Transport and Exchange Surfaces$wdthseed$, $wdthseed$How cells pump substances uphill using energy, and how organs maximise exchange.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Roots absorb minerals from soil even when the soil holds LESS mineral than the root already has — swimming upstream against the gradient. That takes energy, and it is worth it.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Active transport$wdthseed$, $wdthseed$Active transport moves substances from lower to higher concentration — AGAINST the gradient — using energy from respiration (ATP) and carrier proteins in the membrane. It is the only transport process that needs the cell's own energy, so it stops when respiration is blocked (e.g. by cyanide or lack of oxygen). Examples: root hair cells pumping mineral ions (nitrates, phosphates) from dilute soil water; kidney tubule cells reabsorbing all glucose from the filtrate; gut villi absorbing glucose and amino acids into blood after digestion. Comparison table for examinations: diffusion — down gradient, no energy, small molecules/gases; osmosis — water only, down water gradient, needs membrane, no energy; active transport — against gradient, NEEDS energy and carriers, ions and nutrients.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Exchange surfaces$wdthseed$, $wdthseed$Multicellular life needs specialised exchange surfaces, all sharing four adaptations: LARGE surface area, THIN barrier (short diffusion distance), GOOD blood supply or ventilation (to maintain gradients), and MOIST surfaces (gases dissolve before diffusing). Root hairs: millions of tiny extensions giving enormous area for water/mineral uptake. Small-intestine villi: finger-like folds (with microvilli on top) absorbing digested food into dense capillaries. Alveoli: ~300 million air sacs with one-cell-thick walls wrapped in capillaries for gas exchange. Leaves: broad, thin, with stomata and air spaces for CO2 entry. Examination sentence pattern: NAME the adaptation → STATE the feature → EXPLAIN the effect ('Villi increase surface area, so more glucose diffuses into blood per minute').$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: why do roots need oxygen?$wdthseed$, $wdthseed$Question: Waterlogged soil (no air spaces) stunts plant growth even though water is plentiful. Explain using transport processes. Step 1 — Recall: roots absorb mineral ions by ACTIVE transport, which needs ATP from aerobic respiration. Step 2 — Link: waterlogging removes soil oxygen, so root cells cannot respire aerobically and ATP runs out. Step 3 — Conclude: mineral uptake stops, the plant starves of nitrates/phosphates despite sitting in water, so growth stunts and leaves yellow. Bonus: this is why farmers drain waterlogged fields and why overwatering kills potted plants — roots drown, not drink.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Active transport: against the gradient, needs ATP + carrier proteins; poisoned by respiration blockers.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod02:top02:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Cells pay energy to pump vital substances uphill by active transport, and whole organs are sculpted into vast, thin, well-supplied exchange surfaces. Diffusion, osmosis and active transport together explain breathing, feeding, excretion and farming.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod02:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 2 reading: Chapter 4 (Cell Structure) and Chapter 5 (Plasma Membranes: diffusion, osmosis, active transport). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod02:prac$wdthseed$, $wdthseed$Osmosis in Yam Strips$wdthseed$, $wdthseed$Measure how solution concentration affects water movement into and out of plant tissue.$wdthseed$, $wdthseed$You are testing the lesson prediction from Topic 2 with real measurements.$wdthseed$, $wdthseed$1. Cut THREE identical yam (or potato) strips about 5 cm long. Blot dry and weigh or measure each (a ruler + photo works if no scale: measure length to the nearest mm). 2. Place one strip in each: cup A (clean water), cup B (mild salt water — 1 teaspoon per cup), cup C (strong salt water — 4 tablespoons per cup). 3. Leave 30 minutes. Predict first, then observe: remove, blot gently, re-measure. 4. Record results in a table (solution | start | end | change | texture: firm/limp). 5. Write a conclusion linking each result to osmosis and turgor/plasmolysis. SAFETY: wash hands; do not taste the salt solutions; clean spills to avoid slips.$wdthseed$, $wdthseed$Yam or Irish potato, knife (adult help if needed), 3 cups, salt, water, ruler, notebook.$wdthseed$, $wdthseed$A results table with measurements, texture notes, and a 4–6 sentence osmosis conclusion.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 60, $wdthseed$TEXT$wdthseed$, $wdthseed$["Fair test: identical strips, same time, only concentration changed","Table complete with start/end/change for all three cups","Conclusion correctly uses osmosis, water concentration gradient, turgor and plasmolysis"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod02:asg$wdthseed$, $wdthseed$Build and Explain a Cell$wdthseed$, $wdthseed$Construct a 3D or labelled model of a plant OR animal cell and explain how three organelles depend on each other.$wdthseed$, $wdthseed$1. Choose a plant or animal cell. 2. Build a model from household materials (clay, paper, bottle caps, grains of rice for ribosomes...) OR draw a large, fully labelled diagram (minimum 8 labels). 3. Write 300–400 words explaining how THREE organelles cooperate in one real task — e.g. how nucleus + ribosomes + Golgi make and ship an enzyme. 4. Photograph or scan your model/diagram and submit the image description plus your explanation as text (describe colours and materials used). Your explanation must use all three organelle names correctly and show the sequence of events.$wdthseed$, $wdthseed$Original work; models copied from the internet score zero.$wdthseed$, $wdthseed$Model/diagram description + 300–400 word cooperation explanation.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Correct structures for the chosen cell type (plant trio present/absent as appropriate)","Three organelles with accurate functions in a logical sequence","Clear writing with correct biological terms"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod02$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod02:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
