insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod02:exam:quiz:q01$wdthseed$, $wdthseed$A cell has many mitochondria and folded membranes but no chloroplasts or wall. It is most likely:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["A leaf mesophyll cell","A muscle cell","A root hair cell","A bacterial cell"]$wdthseed$::jsonb, $wdthseed$"A muscle cell"$wdthseed$::jsonb, $wdthseed$No wall/chloroplasts rules out plant cells; abundant mitochondria fit an energy-hungry animal cell like muscle. (Root hairs are plant cells with walls.)$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Cell structure"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod02:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
