insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod02:exam:quiz:q03$wdthseed$, $wdthseed$Red blood cells placed in pure water will:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Shrivel (crenate)","Swell and burst (lyse), since water enters by osmosis and there is no wall","Stay exactly the same","Divide by mitosis"]$wdthseed$::jsonb, $wdthseed$"Swell and burst (lyse), since water enters by osmosis and there is no wall"$wdthseed$::jsonb, $wdthseed$Water enters down its gradient; animal cells lack walls to resist the pressure, so they lyse. Plant cells would instead become turgid.$wdthseed$, 3, $wdthseed${"points":1,"topic_tag":"Osmosis"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod02:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
