insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod02:exam:quiz:q05$wdthseed$, $wdthseed$Which adaptation does NOT increase the rate of exchange across a surface?$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Folding to increase surface area","Thinning the barrier","Rich blood supply maintaining gradients","Thickening the barrier to trap substances"]$wdthseed$::jsonb, $wdthseed$"Thickening the barrier to trap substances"$wdthseed$::jsonb, $wdthseed$Thicker barriers slow diffusion (longer distance). Area, thinness, supply and moisture all speed exchange.$wdthseed$, 5, $wdthseed${"points":1,"topic_tag":"Exchange surfaces"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod02:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
