insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod02:exam:quiz:q06$wdthseed$, $wdthseed$Which organelles form the protein production-and-delivery chain? (Select ALL that apply, in any order)$wdthseed$, $wdthseed$multiple_answer$wdthseed$, $wdthseed$["Nucleus (DNA instructions)","Ribosomes (assembly)","Golgi body (packaging and shipping)","Central vacuole (main water store)"]$wdthseed$::jsonb, $wdthseed$["Nucleus (DNA instructions)","Ribosomes (assembly)","Golgi body (packaging and shipping)"]$wdthseed$::jsonb, $wdthseed$DNA instructions (nucleus) → protein assembly (ribosomes, often on rough ER) → packaging/shipping (Golgi). The vacuole stores water, not proteins.$wdthseed$, 6, $wdthseed${"points":2,"topic_tag":"Cell structure"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod02:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
