insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod03$wdthseed$, $wdthseed$Biological Molecules$wdthseed$, $wdthseed$The molecules of life: carbohydrates, lipids, proteins and nucleic acids — plus enzymes and the classic food tests.$wdthseed$, 3, $wdthseed${"objectives":["Describe the structure and roles of carbohydrates, lipids and proteins","Explain how enzymes work and what affects them","Carry out and interpret the four main food tests"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod03:top01$wdthseed$, $wdthseed$Carbohydrates and Lipids$wdthseed$, $wdthseed$Sugars, starch and cellulose; fats and oils — built from C, H and O.$wdthseed$, NULL, 1, TRUE, TRUE, $wdthseed${"objectives":["Classify carbohydrates","Compare fats and oils"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod03$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod03:top01:les01$wdthseed$, $wdthseed$Sugars, Starch and Cellulose$wdthseed$, $wdthseed$From glucose to glycogen: how simple sugars link into energy stores and structural fibres.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=1Dx7LDwINLU$wdthseed$, $wdthseed$Every marathon runner's energy gel, every grain of rice, and the paper of your notebook are all carbohydrates — one family of molecules wearing many uniforms.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The carbohydrate family$wdthseed$, $wdthseed$Carbohydrates contain carbon, hydrogen and oxygen (roughly 1 C : 2 H : 1 O). Monosaccharides are single sugars: glucose (blood sugar, the fuel of respiration), fructose (fruit sugar) and galactose. Disaccharides join two monosaccharides with a glycosidic bond, releasing water (condensation): maltose (glucose + glucose), sucrose (glucose + fructose, table sugar), lactose (glucose + galactose, milk sugar). Polysaccharides chain hundreds together: starch (energy store in plants — amylose + amylopectin in yam, rice, cassava), glycogen (energy store in animals, packed in liver and muscles, more branched for fast release), and cellulose (structural walls of plant cells — long straight chains bundled into tough fibres). Digestion reverses building: hydrolysis ADDS water to split big molecules back into sugars your blood can carry.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Why structure fits function$wdthseed$, $wdthseed$Starch is ideal for storage: compact, coiled, insoluble (so it does not leak out of cells or distort osmosis) yet easily hydrolysed back to glucose on demand. Glycogen's extra branches give animals rapid glucose release during a sprint. Cellulose is built for strength: straight chains hydrogen-bonded into microfibrils with enormous tensile strength — a tree is a cellulose skyscraper. This pattern — structure determining function — repeats for every molecule in this module and is an examination favourite: always link a structural feature to the job it performs.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: condensation vs hydrolysis$wdthseed$, $wdthseed$Question: (a) Two glucose molecules join to form maltose. (b) Starch is digested to glucose in the gut. Name each reaction type and state what happens to water. Step 1 — Recall: joining monomers RELEASES water (condensation); splitting polymers CONSUMES water (hydrolysis). Step 2 — Apply: (a) glucose + glucose → maltose + water is CONDENSATION. (b) Starch + water → glucose units is HYDROLYSIS, catalysed by amylase then maltase. Step 3 — Memory hook: CONdensation CONstructs and water Comes out; HYdrolysis HYDRates (uses water) to break. Examiners award the water detail separately — never omit it.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Biomolecules (Updated 2023)$wdthseed$, $wdthseed$Watch 'Biomolecules (Updated 2023)' by the Amoeba Sisters (official channel stream). Focus on the carbohydrate section now; you will revisit this video for lipids, proteins and nucleic acids in the next lessons.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=1Dx7LDwINLU$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Carbohydrates = C, H, O: monosaccharides (glucose), disaccharides (sucrose, maltose, lactose), polysaccharides (starch, glycogen, cellulose).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Glucose is the hub of carbohydrate biology: linked by condensation into stores (starch, glycogen) and structures (cellulose), freed again by hydrolysis during digestion. Learn the family tree and the water rule, and carbohydrate questions become free marks.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
