insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod03:top01:les02$wdthseed$, $wdthseed$Fats and Oils$wdthseed$, $wdthseed$Triglycerides and phospholipids: concentrated energy, insulation and membranes.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A groundnut is small but keeps you full for hours. Lipids pack more than twice the energy per gram of any sugar — and build every membrane in your body.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Triglycerides and phospholipids$wdthseed$, $wdthseed$A triglyceride joins ONE glycerol to THREE fatty acids by condensation (three ester bonds, three waters released). Fatty acids may be saturated (no double bonds — straight chains that pack tightly, solid at room temperature: butter, palm oil, animal fat) or unsaturated (one or more double bonds kink the chain so it cannot pack — liquid oils: groundnut, soya, olive oil). Roles of lipids: (1) concentrated energy store (9 kcal/g vs 4 for carbohydrate — seeds and adipose tissue); (2) insulation — blubber, subcutaneous fat and myelin sheaths slow heat loss and speed nerve impulses; (3) protection — fat cushions kidneys and eyes; (4) membranes — phospholipids (glycerol + 2 fatty acids + phosphate head) form the bilayer of every cell membrane, with waterproof cuticles and waxes protecting leaves and skin. Steroids (cholesterol, sex hormones) are lipids too, built from rings rather than fatty acids.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les02:blk02$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: why do marathoners hit the wall?$wdthseed$, $wdthseed$Question: Runners store ~2000 kcal as glycogen but ~50,000+ kcal as fat, yet they 'hit the wall' when glycogen runs out. Why can't fat take over instantly? Step 1 — Recall: fat releases energy SLOWLY (needs abundant oxygen and many breakdown steps); glycogen releases it FAST. Step 2 — Apply: at race pace, muscles demand ATP faster than fat oxidation can supply, so pace must drop to the fat-burning rate — the 'wall'. Step 3 — Generalise: biology trades speed against capacity — glycogen is the wallet (fast, small), fat is the bank vault (slow, huge). Examination link: this is why both stores exist; neither alone is optimal.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les02:blk03$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Triglyceride = glycerol + 3 fatty acids (condensation, 3 waters out).
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top01:les02:blk04$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Lipids are energy-dense, waterproof multitaskers: fuel tanks, insulation, cushions and the fabric of membranes. Saturated versus unsaturated explains butter versus oil, and speed-versus-capacity explains why bodies keep both glycogen and fat.$wdthseed$, NULL, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod03:top02$wdthseed$, $wdthseed$Proteins and Enzymes$wdthseed$, $wdthseed$Amino acids, protein shapes, and the biological catalysts that run every cell.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Describe protein structure levels","Explain enzyme action and factors"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod03$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod03:top02:les01$wdthseed$, $wdthseed$Amino Acids and Protein Structure$wdthseed$, $wdthseed$Twenty building blocks, four levels of folding, and jobs from muscle to antibodies.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Hair, enzymes, antibodies, haemoglobin and spider silk are all proteins — one construction kit producing endless machines. The secret is shape.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$From amino acids to proteins$wdthseed$, $wdthseed$Proteins contain C, H, O plus NITROGEN (and sometimes sulphur). Their monomers are 20 amino acids, joined by peptide bonds through condensation into polypeptides. Structure has four levels: PRIMARY — the exact amino-acid sequence (dictated by DNA; one wrong swap causes sickle-cell disease); SECONDARY — local folding into alpha-helices or beta-pleated sheets, held by hydrogen bonds; TERTIARY — the full 3D shape of one chain (this shape IS the function — an enzyme's active site, an antibody's binding site); QUATERNARY — several chains assembled (haemoglobin's four subunits). Heat, strong acids/alkalis and heavy metals disrupt the weak bonds, unfolding the protein — DENATURATION — which destroys function permanently. This is why a boiled egg never un-boils: its albumin proteins are denatured.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Protein jobs$wdthseed$, $wdthseed$Learn five roles with examples: (1) CATALYSIS — enzymes (amylase, catalase); (2) TRANSPORT — haemoglobin carries oxygen, membrane carriers move ions; (3) DEFENCE — antibodies tag germs, fibrinogen clots blood; (4) STRUCTURE — collagen in skin and bone, keratin in hair and nails, actin/myosin in muscle; (5) CONTROL — hormones such as insulin, and receptor proteins that receive signals. Kwashiorkor — the swollen-belly protein deficiency seen in malnourished children — shows what happens when the body cannot build these: stunted growth, weak immunity and fluid imbalance. Beans, soya, groundnuts, eggs, fish and milk are affordable complete-protein sources.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: one swap, one disease$wdthseed$, $wdthseed$Question: In sickle-cell disease, glutamic acid is replaced by valine at ONE position in haemoglobin. Explain why this small change has huge effects. Step 1 — Recall: primary sequence determines tertiary shape; valine is hydrophobic while glutamic acid is hydrophilic. Step 2 — Apply: under low oxygen, the mutant haemoglobin molecules stick together into stiff fibres that distort red cells into sickles. Step 3 — Conclude: sickled cells block capillaries (pain crises) and break down fast (anaemia) — a single amino-acid swap reshapes the protein and cripples its function. This is the sharpest proof that SEQUENCE → SHAPE → FUNCTION.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Proteins = amino-acid chains (peptide bonds); elements C, H, O, N.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Twenty amino acids, folded into precise 3D machines, do most of the cell's work. DNA writes the sequence, shape delivers the function, and anything that unfolds the shape — heat, acid, alkali — breaks the machine.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod03:top02:les02$wdthseed$, $wdthseed$How Enzymes Work$wdthseed$, $wdthseed$Lock-and-key and induced-fit models, and how temperature, pH and concentration change reaction rates.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$Without enzymes, digesting lunch would take years instead of hours. These protein catalysts accelerate reactions millions of times — and this lesson's graphs appear in almost every biology examination.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$The active site$wdthseed$, $wdthseed$Enzymes are globular proteins that speed up (catalyse) specific reactions without being used up. Each enzyme has an ACTIVE SITE — a pocket whose shape fits its SUBSTRATE exactly. The lock-and-key model says the fit is rigid and perfect; the newer induced-fit model says the active site moulds slightly around the substrate, like a glove tightening on a hand — induced fit is the accepted refinement. After binding, the enzyme stresses bonds (or brings reactants together), products leave, and the enzyme is free again. Specificity is absolute: amylase digests starch but ignores protein; each enzyme fits one substrate type. The enzyme-substrate complex is temporary; the enzyme emerges unchanged and ready for the next reaction.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Factors affecting rate$wdthseed$, $wdthseed$Three graphs to master. (1) TEMPERATURE: rate rises with kinetic energy (more successful collisions) to an OPTIMUM (about 37°C for human enzymes), then CRASHES as heat denatures the enzyme — the curve is asymmetric (gentle rise, cliff fall). (2) pH: each enzyme has an optimum pH (pepsin ~pH 2 in the stomach; amylase ~pH 7) with rate falling both sides as charges change shape; extremes denature. (3) SUBSTRATE CONCENTRATION: rate rises then LEVELS OFF (plateau) when every active site is occupied — the enzyme is saturated; only adding more enzyme raises the plateau. Inhibitors: competitive blockers fit the active site (beaten by adding substrate); non-competitive binders distort the enzyme elsewhere (cannot be beaten by substrate). Many drugs and poisons (cyanide, snake venom components) are enzyme inhibitors.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: reading an enzyme graph$wdthseed$, $wdthseed$Question: A student plots amylase activity against temperature and gets a peak at 37°C with zero activity at 80°C. Explain the shape. Step 1 — Describe: rate climbs from 0°C to 37°C, then falls steeply to zero by 80°C. Step 2 — Explain the rise: higher temperature → faster-moving particles → more frequent enzyme-substrate collisions → more complexes per second. Step 3 — Explain the fall: above the optimum, vibrations break the weak bonds holding the active site's shape — the enzyme DENATURES, substrate no longer fits, rate collapses irreversibly. Examination rule: describe the pattern FIRST, then explain each section separately — description and explanation earn separate marks.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Enzymes = specific protein catalysts with an active site; unchanged by the reaction.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top02:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Enzymes work by fit: substrate docks, reaction happens, enzyme repeats. Temperature, pH and substrate concentration sculpt predictable rate curves — learn to describe and explain all three, and enzyme questions become routine.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod03:top03$wdthseed$, $wdthseed$Testing Foods$wdthseed$, $wdthseed$The four classic food tests: starch, reducing sugars, protein and fats.$wdthseed$, NULL, 3, TRUE, TRUE, $wdthseed${"objectives":["Perform the four food tests safely","Interpret positive and negative results"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod03$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod03:top03:les01$wdthseed$, $wdthseed$The Four Food Tests$wdthseed$, $wdthseed$Iodine, Benedict's, biuret and emulsion tests — procedure, colours and safety.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A white powder could be starch, sugar, protein or salt. Four colour-change tests identify it in minutes — and food-test questions are guaranteed marks if you memorise the colours.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top03:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Procedures and colours$wdthseed$, $wdthseed$STARCH — Iodine test: add yellow-brown iodine solution to the sample. Positive: BLUE-BLACK. Negative: stays brown-yellow. (No heating needed.) REDUCING SUGARS (glucose, maltose — NOT sucrose) — Benedict's test: add blue Benedict's solution, then heat in a water bath (never a bare flame). Positive: GREEN → YELLOW → ORANGE → BRICK-RED precipitate as sugar concentration rises. PROTEIN — Biuret test: add sodium hydroxide solution, then a few drops of dilute copper sulphate. Positive: PURPLE/VIOLET. Negative: stays blue. FATS — Emulsion test: shake the sample with ethanol, then pour into water. Positive: MILKY-WHITE EMULSION. (Alternative grease-spot: rub on paper — translucent spot that stays.) Non-reducing sugars (sucrose): boil first with dilute acid, neutralise, THEN Benedict's — a two-step test examiners love.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top03:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Safety and fair testing$wdthseed$, $wdthseed$Benedict's test needs heat: wear eye protection, use a water bath (no open flame near ethanol — it is flammable), point test tubes away from people, and use tongs. Biuret's sodium hydroxide is corrosive — rinse spills with plenty of water and report them. Fair-test rules: same sample size, same reagent volumes, same heating time, and a CONTROL (e.g. distilled water) to prove the reagents alone give negatives. Record results in a table with OBSERVATION (colour seen) and INFERENCE (nutrient present) as separate columns — mixing them loses marks.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top03:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: mystery powder$wdthseed$, $wdthseed$Question: Powder P gives: iodine → stays brown; Benedict's (heated) → brick-red; biuret → stays blue. Identify P's nutrients. Step 1 — Read each test independently: iodine negative = NO starch; Benedict's brick-red = HIGH reducing sugar; biuret negative = NO protein. Step 2 — Combine: P contains abundant reducing sugar (likely glucose) and neither starch nor protein. Step 3 — Present as examiners expect: a three-row table of test/observation/inference, then one concluding sentence. Trap avoided: brick-red proves SUGAR, not starch — starch needs iodine, never Benedict's.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top03:les01:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Iodine → blue-black = STARCH. Benedict's (heated) → green-to-brick-red = REDUCING SUGAR.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod03:top03:les01:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Four tests, four colour stories: iodine blackens starch, Benedict's reddens sugars, biuret purples protein, ethanol milks fats. Memorise reagent + method + colour triples, heat safely, and always run controls.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top03:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod03:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 3 reading: Chapter 3 (Biological Macromolecules) and Chapter 6 (energy, enzymes). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod03$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod03:prac$wdthseed$, $wdthseed$Food Tests in the Kitchen Laboratory$wdthseed$, $wdthseed$Test at least four foods for starch, sugar, protein or fat and record observations and inferences separately.$wdthseed$, $wdthseed$Your kitchen is the lab. Iodine (from a pharmacy/drugstore antiseptic — povidone-iodine diluted) tests starch; the grease-spot test finds fats; and label-reading plus Benedict's logic covers the rest.$wdthseed$, $wdthseed$1. Choose 4 foods (e.g. boiled yam, egg white, groundnut oil, glucose drink). 2. STARCH: place a drop of diluted iodine on a small piece of each — record the exact colour. 3. FAT: rub each food on plain paper, let dry, hold to light — a translucent remaining spot means fat. 4. SUGAR/PROTEIN: read the nutrition labels and copy the sugar and protein grams per 100 g; state which lab test (Benedict's/biuret) would confirm each. 5. Build a table: food | iodine observation | inference | grease-spot | label sugar/protein. 6. Write a conclusion naming the main nutrient of each food. SAFETY: iodine stains skin and clothes (wear gloves/apron); do NOT eat tested samples; keep iodine away from eyes; school-lab students doing real Benedict's/biuret must wear goggles and heat only in a water bath.$wdthseed$, $wdthseed$4 foods, diluted povidone-iodine, plain paper, notebook. (School lab option: Benedict's solution, biuret reagents, water bath, goggles.)$wdthseed$, $wdthseed$A complete results table plus a conclusion naming each food's main nutrient with evidence.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 60, $wdthseed$TEXT$wdthseed$, $wdthseed$["All four foods tested with honest colour/spot observations","Observations and inferences kept in separate columns","Conclusion matches the evidence (e.g. yam = starch, oil = fat)"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod03$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod03:asg$wdthseed$, $wdthseed$Analyse a Day of Eating$wdthseed$, $wdthseed$Record everything one person eats in a day, classify the nutrients, and judge the balance of the diet.$wdthseed$, $wdthseed$1. Record every food and drink one person (you or a volunteer) consumes in 24 hours, with rough quantities. 2. Classify each item's MAIN nutrient (carbohydrate, protein, fat) plus notable vitamins/minerals/fibre/water contributions. 3. Judge the diet against balance rules: energy vs activity, protein for growth/repair, fibre + water, excess sugar/salt/fat risks. 4. Recommend THREE specific, affordable improvements (e.g. 'replace one soft drink with water and groundnuts'). 5. Submit the food diary, classification table and recommendations (350–450 words total).$wdthseed$, $wdthseed$Real data from a real day; invented diaries are easy to spot and score zero.$wdthseed$, $wdthseed$Food diary + nutrient table + three justified improvements.$wdthseed$, $wdthseed$BEGINNER$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Complete honest diary with quantities","Correct main-nutrient classification for every item","Three specific, affordable, biologically justified improvements"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod03$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod03:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
