insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:quiz:q01$wdthseed$, $wdthseed$Which row is correct?$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Starch: plant energy store; Glycogen: animal energy store; Cellulose: plant structure","Starch: animal store; Glycogen: plant store; Cellulose: animal structure","All three are proteins","All three are found only in animals"]$wdthseed$::jsonb, $wdthseed$"Starch: plant energy store; Glycogen: animal energy store; Cellulose: plant structure"$wdthseed$::jsonb, $wdthseed$Plants store starch and build with cellulose; animals store glycogen. All three are polysaccharides of glucose.$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Carbohydrates"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
