insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:quiz:q02$wdthseed$, $wdthseed$A triglyceride is formed from:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["One glycerol + three fatty acids, releasing three waters","Three glycerols + one fatty acid, using three waters","Amino acids joined by peptide bonds","Glucose units joined by glycosidic bonds"]$wdthseed$::jsonb, $wdthseed$"One glycerol + three fatty acids, releasing three waters"$wdthseed$::jsonb, $wdthseed$Condensation joins glycerol to three fatty acids (three ester bonds, three waters out). Amino acids make proteins; glucose chains make polysaccharides.$wdthseed$, 2, $wdthseed${"points":1,"topic_tag":"Lipids"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
