insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:quiz:q03$wdthseed$, $wdthseed$Why does boiling an enzyme permanently destroy its activity?$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["The substrate evaporates","Heat denatures the protein: the active site loses its shape","Boiling adds extra active sites","Enzymes melt into sugars"]$wdthseed$::jsonb, $wdthseed$"Heat denatures the protein: the active site loses its shape"$wdthseed$::jsonb, $wdthseed$Excess heat breaks the weak bonds maintaining tertiary structure, so the active site no longer fits the substrate — irreversible denaturation.$wdthseed$, 3, $wdthseed${"points":1,"topic_tag":"Enzymes"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
