insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:quiz:q05$wdthseed$, $wdthseed$At high substrate concentration, enzyme reaction rate plateaus because:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["All enzymes are denatured","Every active site is occupied — the enzyme is saturated","The product poisons the enzyme","Temperature always falls"]$wdthseed$::jsonb, $wdthseed$"Every active site is occupied — the enzyme is saturated"$wdthseed$::jsonb, $wdthseed$Saturation: with no free active sites, extra substrate must queue. Only adding more enzyme lifts the plateau.$wdthseed$, 5, $wdthseed${"points":1,"topic_tag":"Enzymes"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
