insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:exam:quiz:q01$wdthseed$, $wdthseed$Sucrose gives a negative Benedict's test but a positive one after boiling with acid. The best explanation is:$wdthseed$, $wdthseed$multiple_choice$wdthseed$, $wdthseed$["Sucrose is not a carbohydrate","Sucrose is a non-reducing sugar; acid hydrolysis splits it into glucose + fructose, which are reducing","The acid destroys all sugar","Benedict's only works in acid"]$wdthseed$::jsonb, $wdthseed$"Sucrose is a non-reducing sugar; acid hydrolysis splits it into glucose + fructose, which are reducing"$wdthseed$::jsonb, $wdthseed$Sucrose's glycosidic bond locks both reactive groups (non-reducing). Acid hydrolysis frees glucose and fructose, which then reduce Benedict's.$wdthseed$, 1, $wdthseed${"points":1,"topic_tag":"Carbohydrates"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
