insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:exam:quiz:q04$wdthseed$, $wdthseed$True or False: A competitive inhibitor can be overcome by adding more substrate, because substrate and inhibitor compete for the same active site.$wdthseed$, $wdthseed$true_false$wdthseed$, $wdthseed$["True","False"]$wdthseed$::jsonb, $wdthseed$true$wdthseed$::jsonb, $wdthseed$True. Flooding the active site with substrate out-competes a competitive blocker; non-competitive inhibition (distortion from elsewhere) cannot be beaten this way.$wdthseed$, 4, $wdthseed${"points":1,"topic_tag":"Enzymes"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
