insert into public.quiz_questions (seed_key, question, question_type, options, correct_answer, explanation, order_number, metadata, quiz_id) values ($wdthseed$biology:mod03:exam:quiz:q06$wdthseed$, $wdthseed$Which statements about lipids are TRUE? (Select ALL that apply)$wdthseed$, $wdthseed$multiple_answer$wdthseed$, $wdthseed$["Triglycerides store about twice the energy per gram of carbohydrates","Unsaturated fatty acids have double bonds that kink the chain","All lipids dissolve easily in water","Phospholipids form cell membranes"]$wdthseed$::jsonb, $wdthseed$["Triglycerides store about twice the energy per gram of carbohydrates","Unsaturated fatty acids have double bonds that kink the chain","Phospholipids form cell membranes"]$wdthseed$::jsonb, $wdthseed$Lipids are energy-dense, kinked when unsaturated, and membrane-forming as phospholipids — but they are hydrophobic, NOT water-soluble.$wdthseed$, 6, $wdthseed${"points":2,"topic_tag":"Lipids"}$wdthseed$::jsonb, (select id from public.quizzes where seed_key = $wdthseed$biology:mod03:exam:quiz$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set question = excluded.question, question_type = excluded.question_type, options = excluded.options, correct_answer = excluded.correct_answer, explanation = excluded.explanation, order_number = excluded.order_number, metadata = excluded.metadata, quiz_id = excluded.quiz_id;
