insert into public.course_modules (seed_key, title, description, order_number, metadata, course_id) values ($wdthseed$biology:mod04$wdthseed$, $wdthseed$Cell Division$wdthseed$, $wdthseed$How cells copy themselves: the cell cycle, mitosis for growth and repair, and meiosis for gametes and variation.$wdthseed$, 4, $wdthseed${"objectives":["Describe the stages of the cell cycle and mitosis","Explain the roles of mitosis in growth, repair and asexual reproduction","Describe meiosis and explain how it creates genetic variation"],"duration_text":"1 week"}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, order_number = excluded.order_number, metadata = excluded.metadata, course_id = excluded.course_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod04:top01$wdthseed$, $wdthseed$The Cell Cycle and Mitosis$wdthseed$, $wdthseed$Interphase plus the four stages of mitosis: how one cell becomes two identical cells.$wdthseed$, NULL, 1, TRUE, TRUE, $wdthseed${"objectives":["Order the cell-cycle stages","Explain mitosis roles"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod04$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod04:top01:les01$wdthseed$, $wdthseed$Stages of Mitosis$wdthseed$, $wdthseed$Interphase, prophase, metaphase, anaphase, telophase and cytokinesis — PMAT in full.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=QVCjdNxJreE$wdthseed$, $wdthseed$You began as one cell and now hold about 30 trillion. Every one came from mitosis — the most important dance in biology, performed identically billions of times a day.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Interphase and PMAT$wdthseed$, $wdthseed$The cell cycle is mostly INTERPHASE (growth + DNA replication): the cell grows (G1), copies every chromosome into two sister chromatids (S phase), then grows and prepares to divide (G2). Mitosis itself has four stages — remember PMAT. PROPHASE: chromosomes condense (become visible), the nuclear membrane breaks down, and spindle fibres form. METAPHASE: chromosomes line up singly along the cell equator, attached to spindle fibres at their centromeres. ANAPHASE: sister chromatids are pulled to opposite poles (V-shapes trailing) — the defining moment of exact separation. TELOPHASE: nuclear membranes reform around each set, chromosomes uncoil. CYTOKINESIS then splits the cytoplasm: animal cells pinch inward (cleavage furrow); plant cells build a cell plate outward. Result: TWO genetically IDENTICAL diploid cells, each with the full chromosome number (46 in humans).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Why exactness matters$wdthseed$, $wdthseed$Every chromatid separation must be perfect: lose or gain one chromosome and the daughter cell usually dies or malfunctions (Down syndrome comes from an extra chromosome 21 after a separation error). Spindle checkpoints pause division until every chromosome is attached — the cell proofreads itself. When checkpoints fail and division runs wild, the result is a tumour: cancer is fundamentally a cell-cycle disease. This is why Module 4 matters beyond examinations — chemotherapy drugs target rapidly dividing cells precisely because they exploit mitosis.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: identifying stages$wdthseed$, $wdthseed$Question: Three cells are drawn: A shows chromosomes scattered and condensing with no nuclear membrane; B shows V-shaped chromatids moving apart; C shows two new nuclei with a cell plate. Name each stage. Step 1 — Match diagnostics: scattered condensing chromosomes + no membrane = PROPHASE (A). Chromatids separating toward poles = ANAPHASE (B). Two nuclei + cell plate = TELOPHASE + CYTOKINESIS in a plant cell (C). Step 2 — Justify each with ONE feature (condensing, separating, reforming). Examination tip: anaphase is the only stage with chromatids moving apart — if you see V-shapes travelling, it is anaphase, always.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: The Cell Cycle (and cancer) [Updated]$wdthseed$, $wdthseed$Watch 'The Cell Cycle (and cancer) [Updated]' by the Amoeba Sisters (official channel stream). Note how checkpoints guard each transition — and what happens when they fail.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=QVCjdNxJreE$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Interphase (G1-S-G2): growth and DNA copying — most of the cycle.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Interphase prepares, PMAT divides, cytokinesis splits — producing two exact copies. Precision is enforced by checkpoints because chromosome errors kill cells or cause disease. Learn to recognise each stage from a single diagnostic feature.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
