insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod04:top01:les02$wdthseed$, $wdthseed$Why Mitosis Matters$wdthseed$, $wdthseed$Growth, repair, replacement and asexual reproduction — plus what happens when control is lost.$wdthseed$, $wdthseed$TEXT$wdthseed$::public.lesson_type, NULL, $wdthseed$A cut on your finger closes in days; a broken bone knits in weeks; your gut lining renews itself constantly. All of it is mitosis — until control breaks.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Roles of mitosis$wdthseed$, $wdthseed$Mitosis serves four roles. (1) GROWTH: multicellular organisms grow by cell multiplication — a fertilised egg becomes a baby by repeated mitosis plus cell enlargement. (2) REPAIR: damaged tissues (skin, bone, liver) replace lost cells with identical copies. (3) REPLACEMENT: short-lived cells are renewed continuously — red blood cells (120-day life), gut lining (days), skin surface. (4) ASEXUAL REPRODUCTION: one parent produces genetically identical offspring fast with no mate — binary fission in bacteria, budding in yeast and Hydra, runners in strawberry plants, artificial cloning (cuttings, tissue culture). Advantage: speed and no mate needed; every offspring is proven-suited to a stable environment. Disadvantage: zero variation — one disease can wipe out a whole clone population (the Cavendish banana's crisis).$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Cancer: mitosis out of control$wdthseed$, $wdthseed$Proto-oncogenes normally promote division and tumour-suppressor genes restrain it; mutations can jam the accelerator or cut the brakes, producing cells that divide endlessly, ignore death signals and invade tissues (malignant tumours). Carcinogens that raise mutation risk include tobacco smoke, excessive alcohol, certain viruses (HPV, Hepatitis B), UV radiation and some industrial chemicals. Treatments exploit rapid division: surgery removes, radiotherapy damages, and chemotherapy poisons dividing cells (which is why hair and gut — naturally fast-dividing — suffer side effects). Prevention (no smoking, vaccination, safe sun) beats cure — a public-health message worth spreading in your community.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: clone crisis$wdthseed$, $wdthseed$Question: A farmer plants a whole field with yam setts cut from ONE parent tuber. A new virus arrives. Explain the risk using mitosis. Step 1 — Recall: vegetative propagation is mitosis-based, so all plants are genetically IDENTICAL clones. Step 2 — Apply: resistance genes are the same in every plant — if one plant is vulnerable, ALL are. Step 3 — Conclude: the virus can destroy the entire field, whereas seed-grown (sexual) crops vary and some would survive. Examination link: this contrasts asexual speed/uniformity against sexual variation/resilience — a guaranteed compare question.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les02:blk04$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Mitosis = growth, repair, replacement, asexual reproduction.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top01:les02:blk05$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Mitosis builds, heals and renews you, and clones organisms at speed — but identical copies share identical weaknesses. When division controls mutate, cancer follows. Variation, the subject of meiosis next, is evolution's answer.$wdthseed$, NULL, NULL, 5, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.course_topics (seed_key, title, description, summary, order_number, is_published, published, metadata, course_id, module_id) values ($wdthseed$biology:mod04:top02$wdthseed$, $wdthseed$Meiosis and Variation$wdthseed$, $wdthseed$How gametes halve the chromosome number and shuffle genes to make every individual unique.$wdthseed$, NULL, 2, TRUE, TRUE, $wdthseed${"objectives":["Describe meiosis simply","Explain the two sources of variation"]}$wdthseed$::jsonb, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod04$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, summary = excluded.summary, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, metadata = excluded.metadata, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod04:top02:les01$wdthseed$, $wdthseed$Meiosis Halves the Number$wdthseed$, $wdthseed$One DNA replication, two divisions: from diploid to four unique haploid gametes.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=zrKdz93WlVk$wdthseed$, $wdthseed$If sperm and eggs each carried 46 chromosomes, every generation would double the count until cells burst. Meiosis solves this by halving — with a creative bonus: no two gametes are ever alike.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les01:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Two divisions, one copying$wdthseed$, $wdthseed$Meiosis starts like mitosis: DNA replicates ONCE in interphase. Then come TWO divisions. MEIOSIS I (reduction division): homologous chromosome PAIRS (one from each parent) line up together; in anaphase I, whole HOMOLOGUES separate (not chromatids) — this HALVES the number (46 → 23 in humans). MEIOSIS II: the two cells divide again like mitosis — chromatids separate — giving FOUR haploid cells. In males all four become sperm; in females usually ONE becomes the egg (the rest form polar bodies). Key vocabulary: DIPLOID (2n, paired chromosomes — body cells), HAPLOID (n, single set — gametes), HOMOLOGOUS PAIR (matching chromosomes, one maternal one paternal, same genes in the same order). Fertilisation (n + n) restores 2n — which is why children resemble BOTH parents.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les01:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Mitosis versus meiosis$wdthseed$, $wdthseed$Memorise this comparison — it is examined constantly. DIVISIONS: mitosis 1, meiosis 2. CELLS PRODUCED: 2 vs 4. CHROMOSOME NUMBER: stays diploid vs halved to haploid. GENETIC IDENTITY: identical copies vs all different. LOCATION: body cells (growth/repair) vs reproductive organs (gametes). SEPARATION EVENT: chromatids separate (anaphase) vs homologues separate first (anaphase I), then chromatids. Both begin with DNA replication and share PMAT-like machinery — meiosis is essentially 'mitosis twice with pairing first'. One-line summary: mitosis CLONES, meiosis SHUFFLES AND HALVES.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les01:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: counting chromosomes$wdthseed$, $wdthseed$Question: A fruit-fly body cell has 8 chromosomes. How many chromosomes and chromatids are in: (a) a gamete, (b) a cell in metaphase II? Step 1 — Gamete: meiosis halves 8 → 4 chromosomes, each single-chromatid. Step 2 — Metaphase II: the cell is haploid (4 chromosomes) but each still has TWO chromatids (they separate in anaphase II) → 4 chromosomes, 8 chromatids. Step 3 — State the rule: count CENTROMERES for chromosomes; count DNA strands for chromatids. Trap avoided: chromosomes and chromatids are different counts after replication.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les01:blk04$wdthseed$, $wdthseed$VIDEO$wdthseed$, $wdthseed$Watch: Mitosis vs. Meiosis — Side by Side Comparison$wdthseed$, $wdthseed$Watch 'Mitosis vs. Meiosis: Side by Side Comparison' by the Amoeba Sisters (official channel stream). Pause at the end and write the 6-row comparison table from memory.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=zrKdz93WlVk$wdthseed$, NULL, 4, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les01:blk05$wdthseed$, $wdthseed$KEY_CONCEPTS$wdthseed$, $wdthseed$Key concepts$wdthseed$, $wdthseed$Meiosis = 1 replication + 2 divisions → 4 unique haploid cells.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les01:blk06$wdthseed$, $wdthseed$SUMMARY$wdthseed$, $wdthseed$Lesson summary$wdthseed$, $wdthseed$Meiosis halves the chromosome number through two divisions so fertilisation can restore it. Homologues part in meiosis I, chromatids in meiosis II — and every gamete leaves genetically unique, as the next lesson explains.$wdthseed$, NULL, NULL, 6, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
