insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id, topic_id, lesson_id) values ($wdthseed$biology:mod04:top02:les01:vid1:res$wdthseed$, $wdthseed$Mitosis vs. Meiosis: Side by Side Comparison$wdthseed$, $wdthseed$Direct visual comparison of both divisions — perfect for the classic compare question.$wdthseed$, $wdthseed$https://www.youtube.com/watch?v=zrKdz93WlVk$wdthseed$, $wdthseed$Amoeba Sisters$wdthseed$, $wdthseed$Standard YouTube License (official stream — no copy made)$wdthseed$, $wdthseed$© Amoeba Sisters — streamed from the official channel https://www.youtube.com/@AmoebaSisters$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod04$wdthseed$), (select id from public.course_topics where seed_key = $wdthseed$biology:mod04:top02$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id, topic_id = excluded.topic_id, lesson_id = excluded.lesson_id;
insert into public.lessons (seed_key, title, description, lesson_type, video_url, content, resource_url, duration, order_number, is_published, published, metadata, module_id, topic_id, course_id) values ($wdthseed$biology:mod04:top02:les02$wdthseed$, $wdthseed$Where Variation Comes From$wdthseed$, $wdthseed$Crossing over, independent assortment and random fertilisation — why siblings differ.$wdthseed$, $wdthseed$VIDEO$wdthseed$::public.lesson_type, $wdthseed$https://www.youtube.com/watch?v=VzDMG7ke69g$wdthseed$, $wdthseed$Your parents' genes could combine in trillions of ways — and you are exactly one of them. Meiosis is the shuffling machine behind your uniqueness.
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les02:blk01$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Two shuffles in meiosis$wdthseed$, $wdthseed$Variation source 1 — CROSSING OVER (prophase I): homologous chromosomes press together and swap matching segments, creating chromatids that mix maternal and paternal alleles — brand-new gene combinations on single chromosomes. Variation source 2 — INDEPENDENT ASSORTMENT (metaphase I): each homologous pair lines up randomly, maternal-left or maternal-right, INDEPENDENTLY of other pairs. With 23 pairs, humans produce 2^23 (over 8 MILLION) gamete combinations per person — before crossing over multiplies it further. Then RANDOM FERTILISATION picks one sperm from millions for one egg. Combined, the odds of two identical siblings (excluding identical twins, who split from ONE zygote) are effectively zero. Mutations add brand-new alleles occasionally — the ultimate source of all variation.$wdthseed$, NULL, NULL, 1, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les02:blk02$wdthseed$, $wdthseed$THEORY$wdthseed$, $wdthseed$Why variation matters$wdthseed$, $wdthseed$Variation is evolution's raw material: when environments change (new disease, drought, antibiotic), SOME variants survive and breed — natural selection needs differences to select. Low-variation populations (cheetahs, cloned bananas) face extinction from single threats; high-variation ones adapt. This links Module 4 directly to Module 6 (evolution): meiosis GENERATES the differences that selection SORTS. Sexual reproduction's cost (finding mates, halving gene transmission) is repaid in adaptability — which is why nearly all complex life kept it despite the cost.$wdthseed$, NULL, NULL, 2, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
insert into public.lesson_contents (seed_key, block_type, title, body, url, duration_seconds, order_number, is_published, published, lesson_id) values ($wdthseed$biology:mod04:top02:les02:blk03$wdthseed$, $wdthseed$EXAMPLE$wdthseed$, $wdthseed$Worked example: counting combinations$wdthseed$, $wdthseed$Question: An organism has 3 chromosome pairs. How many gamete types can independent assortment alone produce? Step 1 — Formula: 2^n where n = haploid number (pairs). Step 2 — Substitute: 2^3 = 8 combinations. Step 3 — Interpret: even with 3 pairs there are 8 gamete types; humans with 23 pairs exceed 8 million — and crossing over expands this enormously. Examination note: questions give small numbers (2–4 pairs) for this calculation; state the formula for the method mark.$wdthseed$, NULL, NULL, 3, TRUE, TRUE, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top02:les02$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set block_type = excluded.block_type, title = excluded.title, body = excluded.body, url = excluded.url, duration_seconds = excluded.duration_seconds, order_number = excluded.order_number, is_published = excluded.is_published, published = excluded.published, lesson_id = excluded.lesson_id;
