insert into public.course_resources (seed_key, title, description, url, source, license, attribution, resource_type, is_external, is_approved, course_id, module_id) values ($wdthseed$biology:mod04:res1$wdthseed$, $wdthseed$OpenStax Biology 2e — full textbook (free PDF + web)$wdthseed$, $wdthseed$Module 4 reading: Chapter 10 (Cell Reproduction: mitosis) and Chapter 11 (Meiosis and Sexual Reproduction). Download the free PDF from the publisher page.$wdthseed$, $wdthseed$https://openstax.org/details/books/biology-2e$wdthseed$, $wdthseed$OpenStax, Rice University$wdthseed$, $wdthseed$CC BY-NC-SA 4.0$wdthseed$, $wdthseed$Biology 2e by Mary Ann Clark, Matthew Douglas and Jung Choi (OpenStax, Rice University), licensed CC BY-NC-SA 4.0.$wdthseed$, $wdthseed$BOOK$wdthseed$::public.resource_type, TRUE, TRUE, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod04$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, url = excluded.url, source = excluded.source, license = excluded.license, attribution = excluded.attribution, resource_type = excluded.resource_type, is_external = excluded.is_external, is_approved = excluded.is_approved, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.lesson_practicals (seed_key, title, objective, scenario, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, lesson_id, course_id, module_id) values ($wdthseed$biology:mod04:prac$wdthseed$, $wdthseed$Modelling Mitosis and Meiosis$wdthseed$, $wdthseed$Build physical chromosome models and photograph every stage of mitosis and meiosis in order.$wdthseed$, $wdthseed$School-lab students may prepare real onion root-tip slides; home students build the divisions from craft materials. Both produce a stage-by-stage record.$wdthseed$, $wdthseed$SCHOOL-LAB OPTION: 1. Soften an onion root tip in warm dilute acid, stain with acetic orcein/carmine, squash under a coverslip. 2. Find dividing cells under high power and sketch one cell each for prophase, metaphase, anaphase, telophase. HOME OPTION: 1. Make 4 chromosomes from pipe cleaners or coloured paper strips (2 long, 2 short; one of each pair red = maternal, blue = paternal; use clips for centromeres). 2. Arrange and photograph: interphase, P, M, A, T for mitosis — then prophase I (show crossing over by swapping tips), metaphase I, anaphase I, metaphase II, anaphase II and the 4 gametes for meiosis. 3. Label each photo with the stage and ONE sentence of what is happening. SAFETY: acids and stains need goggles and teacher supervision; wash hands; home modellers keep small parts from young children.$wdthseed$, $wdthseed$Lab: onion root tips, stain, microscope. Home: pipe cleaners/paper, clips, phone camera.$wdthseed$, $wdthseed$5 labelled mitosis stages + 6 labelled meiosis stages (sketches or photos) with one-sentence captions.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Correct stage order with accurate chromosome positions","Crossing over and halving clearly shown in meiosis","Captions use correct terms (homologues, chromatids, haploid)"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$), (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod04$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, objective = excluded.objective, scenario = excluded.scenario, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, lesson_id = excluded.lesson_id, course_id = excluded.course_id, module_id = excluded.module_id;
insert into public.assignments (seed_key, title, description, instructions, requirements, expected_output, difficulty, estimated_time, submission_type, evaluation_criteria, status, max_score, pass_score, course_id, module_id, lesson_id) values ($wdthseed$biology:mod04:asg$wdthseed$, $wdthseed$Mitosis vs Meiosis — The Definitive Comparison$wdthseed$, $wdthseed$Write a structured comparison of the two divisions and explain why the body needs both.$wdthseed$, $wdthseed$1. Draw a comparison table with at least 8 rows (divisions, cells produced, chromosome number, genetic identity, location, separation event, purpose, variation). 2. Write 350–450 words explaining: (a) why growth and healing need mitosis, (b) why reproduction needs meiosis, (c) what would go wrong if gametes were made by mitosis instead (trace two generations of chromosome doubling). 3. End with a 3-sentence summary a JSS student could memorise. Submit the table plus essay as text.$wdthseed$, $wdthseed$Your own words; copied tables score zero.$wdthseed$, $wdthseed$8-row comparison table + 350–450 word explanation + JSS-level summary.$wdthseed$, $wdthseed$INTERMEDIATE$wdthseed$::public.difficulty_level, 90, $wdthseed$TEXT$wdthseed$, $wdthseed$["Table accurate on all 8 rows","Chromosome-doubling consequence traced correctly over generations","Clear JSS summary showing real understanding"]$wdthseed$::jsonb, $wdthseed$PUBLISHED$wdthseed$::public.content_status, 100, 50, (select id from public.courses where slug = $wdthseed$biology$wdthseed$), (select id from public.course_modules where seed_key = $wdthseed$biology:mod04$wdthseed$), (select id from public.lessons where seed_key = $wdthseed$biology:mod04:top01:les01$wdthseed$)) on conflict (seed_key) where seed_key is not null do update set title = excluded.title, description = excluded.description, instructions = excluded.instructions, requirements = excluded.requirements, expected_output = excluded.expected_output, difficulty = excluded.difficulty, estimated_time = excluded.estimated_time, submission_type = excluded.submission_type, evaluation_criteria = excluded.evaluation_criteria, status = excluded.status, max_score = excluded.max_score, pass_score = excluded.pass_score, course_id = excluded.course_id, module_id = excluded.module_id, lesson_id = excluded.lesson_id;
